def to_date(v):
    """Convert common Excel/openpyxl date representations to datetime.date."""
    if v is None:
        return None
    if isinstance(v, dt.datetime):
        return v.date()
    if isinstance(v, dt.date):
        return v
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        try:
            return from_excel(v).date()
        except Exception:
            return None
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y", "%Y/%m/%d", "%m-%d-%Y", "%d-%m-%Y"):
            try:
                return dt.datetime.strptime(s, fmt).date()
            except ValueError:
                pass
        try:
            return dt.datetime.fromisoformat(s).date()
        except Exception:
            return None
    return None

def first_of_month(d):
    return dt.date(d.year, d.month, 1)

def as_number(v):
    if v is None:
        return None
    if isinstance(v, (int, float, Decimal)) and not isinstance(v, bool):
        return float(v)
    if isinstance(v, str):
        s = v.strip().replace(",", "").replace("$", "")
        if not s:
            return None
        try:
            return float(s)
        except ValueError:
            return None
    return None

def inclusive_days(start, end):
    return max(0, (end - start).days + 1)

def overlap_days(a_start, a_end, b_start, b_end):
    start = max(a_start, b_start)
    end = min(a_end, b_end)
    return inclusive_days(start, end)

# Fill only the required answer cells: K7:AA22.
for row in range(7, 23):
    invoice_date = to_date(ws.cell(row, 4).value)  # D
    amount = as_number(ws.cell(row, 7).value)      # G
    bill_start = to_date(ws.cell(row, 8).value)    # H
    bill_end = to_date(ws.cell(row, 9).value)      # I

    if amount is None or invoice_date is None or bill_start is None or bill_end is None or bill_end < bill_start:
        for col in range(11, 28):  # K:AA
            ws.cell(row, col).value = None
        continue

    total_bill_days = inclusive_days(bill_start, bill_end)
    daily_revenue = amount / total_bill_days
    invoice_month_start = first_of_month(invoice_date)

    for col in range(11, 28):  # K:AA
        month_start = to_date(ws.cell(1, col).value)
        month_end = to_date(ws.cell(2, col).value)

        # Fall back to deriving the month end if only the month-start header is present.
        if month_start is None:
            ws.cell(row, col).value = None
            continue
        if month_end is None:
            if month_start.month == 12:
                next_month = dt.date(month_start.year + 1, 1, 1)
            else:
                next_month = dt.date(month_start.year, month_start.month + 1, 1)
            month_end = next_month - dt.timedelta(days=1)

        # No revenue is recognized before the invoice month.  Any service days that
        # predate the invoice month are caught up in the invoice month; subsequent
        # months use the normal overlap with the billing period in H:I.
        if month_start < invoice_month_start:
            recognized_days = 0
        elif month_start == invoice_month_start:
            # Catch-up month: recognize all billable days from the billing-period
            # start through this month end, capped at the billing-period end.
            recognized_days = inclusive_days(bill_start, min(bill_end, month_end))
        else:
            # Later months: recognize the actual service days falling in the month.
            recognized_days = overlap_days(bill_start, bill_end, month_start, month_end)

        value = daily_revenue * recognized_days if recognized_days > 0 else 0
        ws.cell(row, col).value = value

